import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        int[] up = new int[(int) n];
        int[] down = new int[(int) n];
        Arrays.fill(up, 1);
        Arrays.fill(down, 1);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (a[j] < a[i] && up[j] + 1 > up[i]) up[i] = up[j] + 1;
            }
        }
        for (int i = (int) n - 1; i >= 0; i--) {
            for (int j = i + 1; j < n; j++) {
                if (a[j] < a[i] && down[j] + 1 > down[i]) down[i] = down[j] + 1;
            }
        }
        int answer = 0;
        for (int p = 0; p < n; p++) answer = Math.max(answer, up[p] + down[p] - 1);
        System.out.println(answer);
    }
}
